// Compile the system prompt with business context
const business = $input.first().json;
const brief = $('Webhook: Generate Content').first().json.body;

const platforms = brief.platforms || ['x', 'instagram', 'linkedin', 'facebook', 'tiktok', 'youtube'];

// Truncate document context to ~3000 tokens (~12000 chars)
let docContext = business.document_context || '';
if (docContext.length > 12000) {
  docContext = docContext.substring(0, 12000) + '\n[...context truncated for length]';
}

const systemPrompt = `You are a social media content strategist. You create platform-optimised posts for businesses based on their brand voice and content briefs.

=== BRAND CONTEXT ===
${business.context_summary || business.brand_voice || 'No brand context provided.'}

=== BUSINESS BACKGROUND ===
${docContext || 'No additional business documents uploaded.'}

=== PLATFORM RULES ===
Generate one post variant per requested platform. Follow these constraints:

X/Twitter (max 280 chars): Punchy, direct. 1-2 hashtags max. CTA as a hook, not a command. Emojis sparingly.
Instagram (max 2200 chars): Story-driven caption. First line is the hook (visible in feed). Hashtags in a separate block at the end (15-20). Include CTA.
LinkedIn (max 3000 chars): Professional but human. Insight-led opening. Line breaks for readability. No hashtags in body, 3-5 at the end. Thought leadership tone.
Facebook (max 63000 chars): Conversational. Slightly longer than X but shorter than LinkedIn. 2-3 hashtags. Can include link with OG preview.
TikTok (max 4000 chars): Caption for video context. Trend-aware hashtags (5-10). Casual, creator-tone. Include #fyp and niche tags.
YouTube Shorts: Title (max 100 chars) + description (max 5000 chars). Include #Shorts. SEO-friendly.

Only generate variants for these platforms: ${platforms.join(', ')}

=== OUTPUT FORMAT ===
Respond ONLY with valid JSON matching this schema. Do not include markdown fencing or any text outside the JSON:
{
  "x": { "text": "...", "hashtags": ["..."] },
  "instagram": { "caption": "...", "hashtags": ["..."] },
  "linkedin": { "commentary": "...", "hashtags": ["..."] },
  "facebook": { "message": "...", "hashtags": ["..."] },
  "tiktok": { "title": "...", "hashtags": ["..."] },
  "youtube": { "title": "...", "description": "...", "tags": ["..."] },
  "image_prompt": "A suggested image generation prompt based on the content brief and brand style"
}
Only include keys for the requested platforms.`;

return {
  systemPrompt,
  brief: brief.brief,
  business_id: brief.business_id,
  content_id: brief.content_id,
  generate_image: brief.generate_image || false,
  image_prompt_override: brief.image_prompt || null,
  reference_images: business.reference_images || [],
  brand_voice: business.context_summary || business.brand_voice || '',
  platforms
};

// Parse Claude response and extract variants
const response = $input.first().json;
const content = response.content[0].text;

// Clean any markdown fencing
let clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let variants;
try {
  variants = JSON.parse(clean);
} catch (e) {
  return { error: 'Failed to parse Claude response', raw: content };
}

const prev = $('Compile System Prompt').first().json;

return {
  content_id: prev.content_id,
  business_id: prev.business_id,
  variants,
  image_prompt: prev.image_prompt_override || variants.image_prompt || null,
  generate_image: prev.generate_image,
  reference_images: prev.reference_images,
  brand_voice: prev.brand_voice
};

// Build Nano Banana image prompt
const data = $input.first().json;
const refImages = (data.reference_images || []).filter(i => i && i.url).map(i => i.url).slice(0, 4);

const prompt = data.image_prompt || 
  `Professional social media image. Brand: ${data.brand_voice}. Topic: ${data.variants?.image_prompt || 'branded content'}. High quality, no text overlay, suitable for Instagram feed.`;

return {
  prompt,
  image_urls: refImages,
  content_id: data.content_id,
  business_id: data.business_id,
  variants: data.variants,
  aspect_ratio: '1:1',
  num_images: 1
};

// Extract image URL from Nano Banana response
const response = $input.first().json;
const prev = $('Build Image Prompt').first().json;

let imageUrl = null;
if (response.images && response.images.length > 0) {
  imageUrl = response.images[0].url;
} else if (response.output && response.output.images) {
  imageUrl = response.output.images[0].url;
}

return {
  content_id: prev.content_id,
  business_id: prev.business_id,
  variants: prev.variants,
  image_url: imageUrl,
  image_prompt: prev.prompt
};

// No image path — pass through
const data = $input.first().json;
return {
  content_id: data.content_id,
  business_id: data.business_id,
  variants: data.variants,
  image_url: null,
  image_prompt: null
};
